import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'
import { ViewAllPostsButton } from './view-all-posts-button'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

interface PostSummary {
  id: number
  title: string
}

async function getRecentPosts(): Promise<PostSummary[]> {
  const res = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5'
  )
  return res.json()
}

export default async function HomePage() {
  const requestHeaders = await headers()
  const userAgent = requestHeaders.get('user-agent') ?? ''
  const posts = await getRecentPosts()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {new Date().toISOString()}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <ViewAllPostsButton />
    </div>
  )
}

